SandBinderDispenserMaker.productStock = {}; SandBinderDispenserMaker.buildings = {}; SandBinderDispenserMaker.maker = nil; SandBinderDispenserMaker.activeMaking = {}; SandBinderDispenserMaker.totalProducts = 0; SandBinderDispenserMaker.dayTimer = 0
function SandBinderDispenserMaker.init() SandBinderDispenserMaker.ironStock=14; SandBinderDispenserMaker.bronzeStock=12; SandBinderDispenserMaker.woodStock=14; SandBinderDispenserMaker.leatherStock=8; SandBinderDispenserMaker.silverStock=8; SandBinderDispenserMaker.goldStock=6; SandBinderDispenserMaker.jewelStock=4; SandBinderDispenserMaker.pearlStock=4; SandBinderDispenserMaker.productStock={}; SandBinderDispenserMaker.buildings={}; SandBinderDispenserMaker.maker=nil; SandBinderDispenserMaker.activeMaking={}; SandBinderDispenserMaker.totalProducts=0; SandBinderDispenserMaker.dayTimer=0; print("[SandBinderDispenserMaker] Royal Sand Binder Dispenser Maker System initialized (6 products, 4 buildings)") end
function SandBinderDispenserMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SandBinderDispenserMaker.maker={name=n or ("Dajalnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Dajalnik najet: %s (spretnost: %d)",SandBinderDispenserMaker.maker.name,s),"success") end; return true end
function SandBinderDispenserMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SandBinderDispenserMaker.build(id) local ok,e=SandBinderDispenserMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SandBinderDispenserMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SandBinderDispenserMaker.getQualityBonus() local b=0; for _,bd in ipairs(SandBinderDispenserMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SandBinderDispenserMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SandBinderDispenserMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SandBinderDispenserMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SandBinderDispenserMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SandBinderDispenserMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SandBinderDispenserMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SandBinderDispenserMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SandBinderDispenserMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SandBinderDispenserMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SandBinderDispenserMaker.buildings==0 then return false,"Potrebna dajalna delavnica" end; if not SandBinderDispenserMaker.maker then return false,"Potreben dajalnik" end; return true end
function SandBinderDispenserMaker.make(pt,qty) qty=qty or 1; local ok,e=SandBinderDispenserMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SandBinderDispenserMaker.ironStock=SandBinderDispenserMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SandBinderDispenserMaker.bronzeStock=SandBinderDispenserMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SandBinderDispenserMaker.woodStock=SandBinderDispenserMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SandBinderDispenserMaker.leatherStock=SandBinderDispenserMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SandBinderDispenserMaker.silverStock=SandBinderDispenserMaker.silverStock-d.silverCost*qty end; if d.goldCost then SandBinderDispenserMaker.goldStock=SandBinderDispenserMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SandBinderDispenserMaker.jewelStock=SandBinderDispenserMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SandBinderDispenserMaker.pearlStock=SandBinderDispenserMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SandBinderDispenserMaker.maker then t=math.max(1,t-math.floor(SandBinderDispenserMaker.maker.skill/13)) end; table.insert(SandBinderDispenserMaker.activeMaking,{id="sandbinderdispenser_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SandBinderDispenserMaker.completeMaking(m) local q=1.0+(SandBinderDispenserMaker.getQualityBonus()/100); if SandBinderDispenserMaker.maker then q=q+(SandBinderDispenserMaker.maker.skill/140) end; q=math.min(2.5,q); SandBinderDispenserMaker.productStock[m.productType]=(SandBinderDispenserMaker.productStock[m.productType] or 0)+m.quantity; SandBinderDispenserMaker.totalProducts=SandBinderDispenserMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SandBinderDispenserMaker.maker then SandBinderDispenserMaker.maker.itemsMade=SandBinderDispenserMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SandBinderDispenserMaker.maker.skill=math.min(100,SandBinderDispenserMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Dajalnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"sandbinderdispenser.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function SandBinderDispenserMaker.update(dt) if not _G.state then return end; SandBinderDispenserMaker.dayTimer=SandBinderDispenserMaker.dayTimer+dt; if SandBinderDispenserMaker.dayTimer>=30 then SandBinderDispenserMaker.dayTimer=0; for i=#SandBinderDispenserMaker.activeMaking,1,-1 do local m=SandBinderDispenserMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SandBinderDispenserMaker.completeMaking(m); table.remove(SandBinderDispenserMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SandBinderDispenserMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SandBinderDispenserMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SandBinderDispenserMaker.getStats() return {ironStock=SandBinderDispenserMaker.ironStock,bronzeStock=SandBinderDispenserMaker.bronzeStock,woodStock=SandBinderDispenserMaker.woodStock,leatherStock=SandBinderDispenserMaker.leatherStock,silverStock=SandBinderDispenserMaker.silverStock,goldStock=SandBinderDispenserMaker.goldStock,jewelStock=SandBinderDispenserMaker.jewelStock,pearlStock=SandBinderDispenserMaker.pearlStock,productStock=SandBinderDispenserMaker.productStock,numBuildings=#SandBinderDispenserMaker.buildings,hasMaker=SandBinderDispenserMaker.maker~=nil,makerName=SandBinderDispenserMaker.maker and SandBinderDispenserMaker.maker.name or "—",makerSkill=SandBinderDispenserMaker.maker and SandBinderDispenserMaker.maker.skill or 0,activeMaking=#SandBinderDispenserMaker.activeMaking,totalProducts=SandBinderDispenserMaker.totalProducts} end
